<template>
  <section class="tc-page" aria-label="队伍盯控">
    <header class="tc-intro"><div class="tc-ribbon-row"><h2>{{ title }}</h2><div class="tc-heading-meta"><span><i :style="icon('location')"/>{{ scopeLabel }}</span><span>月数据截至 {{ data?.statDate || metadata?.statDate || (metaBusy?'加载中…':'暂无') }}</span><em v-if="demo">示意数据</em></div><button type="button" class="tc-refresh" :disabled="busy||metaBusy" @click="refresh" aria-label="刷新队伍盯控">↻<small>刷新</small></button></div></header>
    <form class="tc-filters" @submit.prevent="apply">
      <div class="tc-scope-row"><label>分公司<select v-model="draft.branchId" aria-label="盯控分公司" :disabled="permission.role!=='city'" @change="draft.gridId='' "><option value="">全市</option><option v-for="b in org.branches" :key="b.branchId" :value="b.branchId">{{ b.branchName }}</option></select></label><label>网格<select v-model="draft.gridId" aria-label="盯控网格" :disabled="permission.role==='grid'"><option value="">全部网格</option><option v-for="g in availableGrids" :key="g.gridId" :value="g.gridId">{{ g.gridName }}</option></select></label><label class="tc-product-filter">产品<select v-model="draft.productId" aria-label="盯控产品"><option v-for="p in products" :key="p.productId" :value="p.productId">{{ p.productName }}</option></select></label></div>
      <div class="tc-criteria"><header><strong>盯控标准</strong><button type="button" :aria-expanded="rulesOpen" @click="rulesOpen=!rulesOpen">调整标准 {{ rulesOpen?'⌃':'⌄' }}</button></header><p><b class="tc-low-pill">低产</b>本月产能 ≤ {{ format(state.threshold) }}{{ unit }}，含零产</p><p><b class="tc-change-pill">异动</b>较上月日均下降率 ≥ {{ format(state.declineRate) }}%，且减少 ≥ {{ format(state.declineValue) }}{{ unit }}/日</p><small>进入页面按默认标准统计，可自定义调整</small><div v-if="rulesOpen" class="tc-rule-inputs"><label>低产上限<input v-model.number="draft.threshold" type="number" min="0" step="any" required aria-label="低产上限"/></label><label>较上月日均下降率（%）<input v-model.number="draft.declineRate" type="number" min="0" max="100" step="any" required aria-label="异动下降率"/></label><label>日均减少值<input v-model.number="draft.declineValue" type="number" min="0" step="any" required aria-label="异动减少值"/></label></div></div>
      <div class="tc-actions"><button type="submit" :disabled="busy">{{ busy?'统计中…':'筛选' }}</button><button type="button" @click="reset">重置默认</button></div><button v-if="!state.managerCode" type="button" class="tc-export" :disabled="busy||exportBusy||!data?.statDate" @click="exportDetails">{{ exportBusy?'正在导出…':'下载低产与异动明细' }}</button>
    </form>
    <p v-if="exportError" class="tc-error" role="alert">{{ exportError }}</p><p v-if="error" class="tc-error" role="alert">{{ error }} <button @click="load">重试</button></p><p v-if="!busy && data && !data.statDate" class="tc-error">暂无月度统计基准日期，暂不判断低产和异动。</p>
    <template v-if="data && !error">
      <button v-if="state.team" type="button" class="tc-back" @click="back">‹ {{ state.managerCode?'返回网格经理队伍':'返回队伍总览' }}</button>
      <template v-if="!manager"><h3 v-if="!state.team" class="tc-section-heading">总体概览</h3><p v-if="!state.team" class="tc-overview-note">统计行随销、营业厅、3星+渠道、末梢渠道，不含网格经理。</p><div class="tc-summary" aria-label="队伍规模统计"><div><span>{{ state.team?'总规模':'总规模' }}</span><strong>{{ format(summary.total) }}<small>{{ state.team?activeTeam?.unit:'' }}</small></strong></div><div><span>{{ state.team==='own'?'低产人数':'低产规模' }}</span><strong class="tc-orange">{{ format(summary.low) }}<small>{{ state.team?activeTeam?.unit:'' }}</small></strong></div><div><span>{{ state.team==='own'?'异动人数':'异动规模' }}</span><strong class="tc-red">{{ format(summary.change) }}<small>{{ state.team?activeTeam?.unit:'' }}</small></strong></div></div></template>
      <template v-if="!state.team">
        <section v-if="!state.gridId" class="tc-region"><h3 class="tc-section-heading">{{ state.branchId?'网格盯控看板':'分公司盯控看板' }}</h3><div class="tc-matrix-scroll" tabindex="0" aria-label="区域盯控看板，低产和异动分别合并行展示"><table class="tc-matrix"><colgroup><col class="tc-type-col"/><col class="tc-area-col"/><col v-for="team in matrixTeams" :key="team.id"/></colgroup><thead><tr><th>类型</th><th>{{ state.branchId?'网格':'分公司' }}</th><th v-for="team in matrixTeams" :key="team.id">{{ team.name }}</th></tr></thead><tbody><template v-for="metric in matrixMetrics" :key="metric.key"><tr v-for="(region,index) in data.regions" :key="metric.key+region.id" :class="{'tc-matrix-group-start':index===0&&metric.key==='changeRate'}"><th v-if="index===0" scope="rowgroup" :rowspan="data.regions.length" class="tc-matrix-type" :class="metric.key==='lowRate'?'tc-type-low':'tc-type-change'">{{ metric.label }}</th><th scope="row"><button type="button" @click="openRegion(region)" :title="region.name">{{ shortName(region.name) }}</button></th><td v-for="cell in region.cells" :key="cell.team" :class="heat(cell.team,metric.key,cell[metric.key])">{{ rate(cell[metric.key]) }}</td></tr></template></tbody></table></div><p class="tc-matrix-note">同类型、同队伍比例最高标红，最低标绿</p></section>
        <header class="tc-section-heading tc-team-heading"><h3>五类队伍</h3><span>点击查看对象明细</span></header>
        <div class="tc-team-list"><button v-for="team in data.teams" :key="team.id" class="tc-team-row" type="button" @click="openTeam(team.id)"><span class="tc-avatar" :class="team.id"><i :style="icon(team.id==='own'?'users':team.id==='people'?'user':team.id==='stars'?'star':'store')"/></span><span class="tc-team-name"><strong>{{ team.name }}</strong><small v-if="team.id==='own'">本人＋所管对象</small></span><span class="tc-team-stat"><small>规模</small><strong>{{ format(team.total) }}<em>{{ team.unit }}</em></strong></span><span class="tc-team-stat"><small>低产</small><strong class="tc-orange">{{ format(team.low) }}</strong></span><span class="tc-team-stat"><small>异动</small><strong class="tc-red">{{ format(team.change) }}</strong></span><span class="tc-chevron">›</span></button></div><p class="tc-count-note">人员与渠道按各自对象计数；低产与异动可能重叠，不相加统计。</p>
      </template>
      <template v-else>
        <section v-if="manager" class="tc-object-card tc-manager-summary"><div class="tc-person-heading"><span class="tc-avatar own"><i :style="icon('user')"/></span><div><h3>{{ manager.name }}</h3><span class="tc-role own">{{ displayRole(manager.role) }}</span><p>{{ shortName(manager.branchId) }} · {{ gridName(manager.gridId) }}</p></div></div><h4>本人＋所管对象汇总 · {{ productName }}</h4><MetricPair :metric="manager.metric"/></section>
        <section v-if="state.team==='own' && !manager" class="tc-roles"><header class="tc-section-heading"><h3>岗位盯控</h3><span>点击岗位筛选名单</span></header><button v-for="row in data.roles" :key="row.role" class="tc-role-row" :class="{selected:state.role===row.role}" @click="selectRole(row.role)"><i :style="icon('user')"/><strong>{{ row.role }}</strong><span><small>规模</small>{{ format(row.stats.total) }}人</span><span class="tc-orange"><small>低产</small>{{ format(row.stats.low) }}人</span><span class="tc-red"><small>异动</small>{{ format(row.stats.change) }}人</span></button><div v-if="state.role" class="tc-selected">已选：<button @click="selectRole('')">{{ state.role }} ×</button><button class="tc-all-roles" @click="selectRole('')">查看全部岗位 ›</button></div></section>
        <div v-if="manager" class="tc-relations"><button v-for="r in ['本人','所管人员','所管渠道']" :key="r" :class="{active:state.relation===r}" @click="state.relation=r;state.page=1">{{ r }}</button></div>
        <div v-if="state.team==='people'" class="tc-job-filter"><button v-for="r in ['','行销经理','商企经理','装维随销']" :key="r" :class="{active:state.role===r}" @click="selectRole(r)">{{ r||'全部岗位' }}</button></div>
        <div class="tc-tabs" role="group" aria-label="盯控分类"><button v-for="f in filters" :key="f.id" :class="{active:state.filter===f.id}" :aria-pressed="state.filter===f.id" @click="state.filter=f.id;state.page=1">{{ f.label }}</button></div>
        <label class="tc-search"><i :style="icon('search')"/><input v-model="state.query" type="search" maxlength="100" :placeholder="state.team==='people'||state.team==='own'?'搜索姓名 / 工号':'搜索渠道名称 / 编码'" aria-label="搜索盯控对象" @input="state.page=1"/></label>
        <p class="tc-result-count">{{ busy?'统计中…':`共 ${format(data.pagination.total)} ${state.managerCode&&state.relation==='所管渠道'?'个渠道':state.team==='own'||state.team==='people'?'人':'个对象'}` }}</p>
        <article v-for="item in busy?[]:data.items" :key="item.key" class="tc-object-card" :class="{'tc-is-change':item.metric.change}"><header class="tc-person-heading"><span class="tc-avatar" :class="item.isOwn?'own':item.team"><i :style="icon(item.isOwn||item.entityType==='staff'||item.team==='people'?'user':'store')"/></span><div class="tc-person-copy"><h3>{{ item.name || '名称未维护' }}</h3><div class="tc-identifiers"><span class="tc-role" :class="{own:item.isOwn}">{{ displayRole(item.role) }}</span><span v-if="showCode(item)">{{ item.team==='people'||item.isOwn?'工号':'编码' }} {{ item.code }}</span></div><p>{{ item.branchId }} · {{ gridName(item.gridId) }}</p></div><div class="tc-flags"><span v-if="item.metric.low" class="low">低产</span><span v-if="item.metric.change" class="change">异动</span></div></header><div v-if="!item.isOwn" class="tc-managers"><span v-for="m in item.managers||[]" :key="m.code">看管人 {{ m.name }} · {{ displayRole(m.role) }}</span><small v-if="!item.managers?.length">暂无看管信息</small></div><h4>产品：{{ productName }}</h4><MetricPair :metric="item.metric"/><footer v-if="item.isOwn&&!state.managerCode"><small>本人＋当前所管对象汇总</small><button type="button" @click="openManager(item.code)">查看本人及所管明细 ›</button></footer></article>
        <p v-if="!busy && !data.items.length" class="tc-empty">当前条件下暂无匹配对象</p><div class="tc-pagination" v-if="data.pagination.total>30"><button :disabled="state.page===1" @click="state.page--">上一页</button><span>第 {{ state.page }} 页</span><button :disabled="!data.pagination.hasMore" @click="state.page++">下一页</button></div>
      </template>
    </template>
  </section>
</template>
<script setup>
import {computed,defineComponent,h,onBeforeUnmount,reactive,ref,watch,nextTick} from 'vue'
import {fetchTeamControl,fetchTeamControlMeta} from '../api/production.js'
import {productDisplayText} from '../utils/productVisibility.js'
import {cachedTeamControl,clearTeamControlCache} from '../utils/teamControlCache.js'
import { normalizeTeamResponse,teamOverview } from '../utils/teamControlResponse.js'
import { downloadTeamWorkbook } from '../utils/teamControlExport.js'
import personIcon from '../assets/ui-icons/user-round.svg'
import storeIcon from '../assets/ui-icons/store.svg'
import usersIcon from '../assets/ui-icons/users-round.svg'
import starIcon from '../assets/ui-icons/store-star.svg'
import searchIcon from '../assets/ui-icons/search.svg'
import locationIcon from '../assets/ui-icons/map-pin.svg'
const props=defineProps({permission:Object,products:Array,token:String,demo:Boolean,navigationState:Object})
const emit=defineEmits(['navigation-change'])
const defaults={branchId:'',gridId:'',productId:'newNumbers',threshold:1,declineRate:10,declineValue:1,team:'',managerCode:'',relation:'本人',role:'',filter:'low',query:'',page:1}
const initial={...defaults,...props.navigationState};if(!['low','change'].includes(initial.filter))initial.filter='low'
const state=reactive(initial),draft=reactive({...state}),data=ref(null),busy=ref(false),error=ref(''),rulesOpen=ref(false)
const metadata=ref(null),metaBusy=ref(false);let metaRequest=null
const filters=[{id:'low',label:'低产'},{id:'change',label:'异动'}]
const format=v=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2})
const rate=v=>v==null?'—':format(Math.round(v*10)/10)+'%'
const displayRole=v=>v==='商企经理1'?'商企经理':v
const shortName=v=>String(v||'').replace(/分公司$/,'')
const org=computed(()=>metadata.value?.organization||data.value?.organization||{branches:[],grids:[]})
const availableGrids=computed(()=>org.value.grids.filter(g=>!draft.branchId||g.branchId===draft.branchId))
const activeTeam=computed(()=>data.value?.teams.find(t=>t.id===state.team))
const matrixMetrics=[{label:'低产',key:'lowRate'},{label:'异动',key:'changeRate'}]
const matrixTeams=computed(()=>data.value?.teams.filter(t=>t.id!=='own')||[])
const manager=computed(()=>state.managerCode && data.value?.manager?.code===state.managerCode ? data.value.manager : null)
const title=computed(()=>(manager.value?'网格经理明细':'')|| (state.team?(activeTeam.value?.name||'队伍')+'盯控':'队伍盯控'))
const scopeLabel=computed(()=>state.gridId?gridName(state.gridId):state.branchId||'中山市')
const summary=computed(()=>state.team?data.value?.summary:teamOverview(data.value?.teams||[]))
const productName=computed(()=>productDisplayText(props.products.find(p=>p.productId===state.productId)?.productName||state.productId))
const unit=computed(()=>props.products.find(p=>p.productId===state.productId)?.unit||'户')
const gridName=id=>org.value.grids.find(g=>g.gridId===id)?.gridName||String(id||'').split('::').slice(1).join('::')||'网格未维护'
const showCode=item=>item.code&&!String(item.code).startsWith('tail:')&&item.role!=='末梢渠道'
const icon=name=>({'--tc-icon':`url("${({location:locationIcon,user:personIcon,users:usersIcon,store:storeIcon,star:starIcon,search:searchIcon})[name]}")`})
function heat(team,key,value){if(value==null)return '';const values=data.value.regions.flatMap(r=>r.cells.filter(c=>c.team===team).map(c=>c[key])).filter(v=>v!=null);if(!values.length)return '';const min=Math.min(...values),max=Math.max(...values);return min===max?'':value===max?'tc-high':value===min?'tc-lowest':''}
function apply(){clearTeamControlCache(cacheIdentity());if(!Number.isFinite(Number(draft.threshold))||draft.threshold<0||!Number.isFinite(Number(draft.declineRate))||draft.declineRate<0||draft.declineRate>100||!Number.isFinite(Number(draft.declineValue))||draft.declineValue<0){error.value='请填写有效的非负盯控标准，下降率须为0至100%';return}Object.assign(state,{branchId:draft.branchId,gridId:draft.gridId,productId:draft.productId,threshold:draft.threshold,declineRate:draft.declineRate,declineValue:draft.declineValue,page:1,managerCode:''});if(JSON.stringify(lastParams)===JSON.stringify(params()))load()}
function reset(){Object.assign(draft,{threshold:1,declineRate:10,declineValue:1});apply()}
function selectRole(role){state.role=role;state.page=1}
function openTeam(team){Object.assign(state,{team,role:'',filter:'low',query:'',page:1,managerCode:''});top()}
function openManager(code){Object.assign(state,{managerCode:code,filter:'low',query:'',page:1,relation:'本人'});top()}
function back(){if(state.managerCode)state.managerCode='';else Object.assign(state,{team:'',role:'',filter:'low',query:'',page:1});top()}
function openRegion(region){if(state.branchId){state.gridId=region.id;draft.gridId=region.id}else{state.branchId=region.id;draft.branchId=region.id;state.gridId='';draft.gridId=''}state.page=1}
function top(){nextTick(()=>window.scrollTo({top:0}))}
const params=()=>({...state,phone:props.permission.phone})
const cacheIdentity=()=>({token:props.token,permission:props.permission});const exportBusy=ref(false);let exportError=ref('')
let sequence=0,timer,lastParams=null
async function exportDetails(){if(exportBusy.value)return;exportBusy.value=true;exportError.value='';try{await downloadTeamWorkbook({queryApi:fetchTeamControl,params:params(),token:props.token,productName:productName.value,scope:scopeLabel.value,demo:props.demo});}catch(e){exportError.value=e.message||'导出失败，请重试'}finally{exportBusy.value=false}}
async function refresh(){if(busy.value||metaBusy.value)return;clearTeamControlCache(cacheIdentity());metadata.value=null;await load()}
async function loadMeta(){
 if(metadata.value)return metadata.value;
 if(metaRequest)return metaRequest;
 metaBusy.value=true;
 metaRequest=cachedTeamControl(cacheIdentity(),'metadata',{},()=>fetchTeamControlMeta({phone:props.permission.phone},props.token)).then(result=>{
  metadata.value=result;
  if(props.permission.role!=='city'&&!state.branchId&&result.organization.branches.length===1){
   state.branchId=result.organization.branches[0].branchId;draft.branchId=state.branchId;
   if(props.permission.role==='grid'&&result.organization.grids.length===1){state.gridId=result.organization.grids[0].gridId;draft.gridId=state.gridId}
  }
  return result;
 }).finally(()=>{metaBusy.value=false;metaRequest=null});
 return metaRequest;
}
async function load(){const id=++sequence;busy.value=true;error.value='';const request=params();lastParams=request;try{const result=await Promise.all([cachedTeamControl(cacheIdentity(),'statistics',request,()=>fetchTeamControl(request,props.token)),loadMeta()]).then(results=>normalizeTeamResponse(results[0]));if(id!==sequence)return;data.value=result;
 if(props.permission.role!=='city'&&!state.branchId&&result.organization.branches.length===1){const branchId=result.organization.branches[0].branchId;Object.assign(state,{branchId});draft.branchId=branchId;if(props.permission.role==='grid'&&result.organization.grids.length===1){state.gridId=result.organization.grids[0].gridId;draft.gridId=state.gridId}}
 }catch(e){if(id===sequence)error.value=e.message||'队伍盯控查询失败'}finally{if(id===sequence)busy.value=false}}
watch(()=>JSON.stringify(state),()=>{clearTimeout(timer);sequence++;busy.value=true;timer=setTimeout(load,180);emit('navigation-change',JSON.parse(JSON.stringify(state)))},{immediate:true})
watch(()=>JSON.stringify(props.navigationState),()=>{const next={...defaults,...props.navigationState};if(!['low','change'].includes(next.filter))next.filter='low';if(JSON.stringify(next)!==JSON.stringify(state)){Object.assign(state,next);Object.assign(draft,next)}})
onBeforeUnmount(()=>{clearTimeout(timer);sequence++})
const MetricPair=defineComponent({props:{metric:Object},setup(p){return()=>{const m=p.metric||{},signed=v=>`${v>0?'+':''}${format(v)}`;return h('div',{class:'tc-metric-block'},[
 h('div',{class:'tc-pair'},[h('div',[h('span','本月累计'),h('strong',[format(m.month),h('small',m.unit)])]),h('div',[h('span','上月同期'),h('strong',[format(m.previous),h('small',m.unit)])])]),
 h('p',{class:'tc-averages'},`本月日均 ${format(m.monthAverage)} · 上月同期日均 ${format(m.previousAverage)} ${m.unit||'户'}/日`),
 h('p',{class:['tc-change-text',m.changeValue<0?'down':m.changeValue>0?'up':'']},m.changeValue==null?'暂无可比数据':`较上月同期日均 ${signed(m.changeValue)} ${m.unit||'户'}/日${m.changeRate==null?'（上期为0，变化率不适用）':`（${signed(m.changeRate)}%）`}`)
 ])}}})
</script>
<style scoped>
